label("$B$",(5,8),N);
label("$C$",(5,0),S);
label("$D$",(0,0),S);
label("$A$",(8,8),N);
label("$B$",(13,8),N);
label("$C$",(8,5),W);
label("$D$",(8,0),S);
label("$P$",(13,5),E);
label("$A$",(16,8),N);
label("$B$",(21,8),N);
label("$C$",(21,0),S);
label("$D$",(16,0),S);
label("$P$",(21,5),E);
label("$Q$",(21,3),E);
label("$R$",(20,4),W);
[/asy]

